const event = $json.body;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!event || typeof event !== 'object' || Array.isArray(event) || Object.keys(event).some(k => !['type','leadId','incomingMessageId','profileUpdatedAt'].includes(k)) || event.type !== 'lead.preferences.updated' || typeof event.leadId !== 'string' || !uuid.test(event.leadId) || typeof event.incomingMessageId !== 'string' || !uuid.test(event.incomingMessageId) || typeof event.profileUpdatedAt !== 'string' || event.profileUpdatedAt.length > 40 || !Number.isFinite(Date.parse(event.profileUpdatedAt))) throw new Error('Evento inválido; nenhum envio realizado.');
return [{ json: { type: event.type, leadId: event.leadId, incomingMessageId: event.incomingMessageId, profileUpdatedAt: event.profileUpdatedAt } }];
